-- Batch 9a: controlled Weakness Analysis / FORM-010 foundation.
CREATE FUNCTION public.can_manage_weakness_analysis() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER
SET search_path=pg_catalog,public AS $$ SELECT public.is_admin_identity() OR public.current_auditor_is_lead_auditor() $$;

CREATE TABLE public.weakness_analysis_reports(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), judul text NOT NULL CHECK(btrim(judul)<>''),
 source_mode text NOT NULL CHECK(source_mode IN('DATE_RANGE','PROGRAM')), periode_mulai date, periode_selesai date,
 program_id uuid REFERENCES public.audit_programs(id) ON DELETE RESTRICT, tanggal date NOT NULL DEFAULT current_date,
 kesimpulan text, status text NOT NULL DEFAULT 'Draft' CHECK(status IN('Draft','Final')),
 kode_dokumen text NOT NULL DEFAULT 'Q-120-ISE-001-FORM-010-REV.0' CHECK(kode_dokumen='Q-120-ISE-001-FORM-010-REV.0'),
 revision_version integer NOT NULL DEFAULT 1 CHECK(revision_version>0), finalized_at timestamptz,
 audit_team_leader_auditor_id uuid REFERENCES public.auditors(id) ON DELETE RESTRICT,
 audit_team_leader_name_snapshot text, pj_qms text, pj_qms_snapshot text,
 created_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT weakness_source_consistency CHECK((source_mode='DATE_RANGE' AND periode_mulai IS NOT NULL AND periode_selesai IS NOT NULL AND periode_selesai>=periode_mulai AND program_id IS NULL) OR (source_mode='PROGRAM' AND program_id IS NOT NULL AND periode_mulai IS NULL AND periode_selesai IS NULL)),
 CONSTRAINT weakness_final_consistency CHECK((status='Draft' AND finalized_at IS NULL) OR (status='Final' AND finalized_at IS NOT NULL))
);
CREATE TABLE public.weakness_analysis_report_items(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES public.weakness_analysis_reports(id) ON DELETE RESTRICT,
 finding_id uuid NOT NULL REFERENCES public.findings(id) ON DELETE RESTRICT, car_id uuid NOT NULL REFERENCES public.cars(id) ON DELETE RESTRICT,
 sort_order integer NOT NULL CHECK(sort_order>0), final_4m1e text CHECK(final_4m1e IN('MAN','MACHINE','METHOD','MATERIAL','ENVIRONMENT')),
 final_dis text CHECK(final_dis IN('DOKUMEN','IMPLEMENTASI','SISTEM')), final_problem_type text CHECK(final_problem_type IN('A','B','C','D','E')),
 UNIQUE(report_id,finding_id),UNIQUE(report_id,car_id),UNIQUE(report_id,sort_order)
);
CREATE TABLE public.ltp_analysis_classifications(
 car_id uuid PRIMARY KEY REFERENCES public.cars(id) ON DELETE RESTRICT,
 approved_4m1e text NOT NULL CHECK(approved_4m1e IN('MAN','MACHINE','METHOD','MATERIAL','ENVIRONMENT')),
 approved_dis text NOT NULL CHECK(approved_dis IN('DOKUMEN','IMPLEMENTASI','SISTEM')),
 approved_problem_type text NOT NULL CHECK(approved_problem_type IN('A','B','C','D','E')),
 approved_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT, approved_at timestamptz NOT NULL DEFAULT now(),
 approval_source text NOT NULL CHECK(approval_source IN('MANUAL','AI_ACCEPTED','AI_EDITED')),
 created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.ltp_ai_classification_suggestions(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),car_id uuid NOT NULL REFERENCES public.cars(id) ON DELETE RESTRICT,
 weakness_report_id uuid REFERENCES public.weakness_analysis_reports(id) ON DELETE RESTRICT,provider text NOT NULL DEFAULT 'OPENAI' CHECK(provider='OPENAI'),
 model text NOT NULL,prompt_version text NOT NULL,input_hash text NOT NULL,
 suggested_4m1e text NOT NULL CHECK(suggested_4m1e IN('MAN','MACHINE','METHOD','MATERIAL','ENVIRONMENT')),
 suggested_dis text NOT NULL CHECK(suggested_dis IN('DOKUMEN','IMPLEMENTASI','SISTEM')),suggested_problem_type text NOT NULL CHECK(suggested_problem_type IN('A','B','C','D','E')),
 confidence_4m1e numeric NOT NULL CHECK(confidence_4m1e BETWEEN 0 AND 1),confidence_dis numeric NOT NULL CHECK(confidence_dis BETWEEN 0 AND 1),confidence_problem_type numeric NOT NULL CHECK(confidence_problem_type BETWEEN 0 AND 1),
 alasan_singkat text NOT NULL CHECK(btrim(alasan_singkat)<>'' AND char_length(alasan_singkat)<=1000),input_tokens integer,output_tokens integer,total_tokens integer,provider_request_id text,
 generated_by uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.weakness_why_analysis(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid NOT NULL REFERENCES public.weakness_analysis_reports(id) ON DELETE RESTRICT,nomor integer NOT NULL CHECK(nomor>0),problem text NOT NULL,akar_permasalahan text NOT NULL,sort_order integer NOT NULL CHECK(sort_order>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(report_id,sort_order));
CREATE TABLE public.weakness_why_levels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),why_analysis_id uuid NOT NULL REFERENCES public.weakness_why_analysis(id) ON DELETE CASCADE,level integer NOT NULL CHECK(level BETWEEN 1 AND 4),teks text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(why_analysis_id,level));
CREATE TABLE public.weakness_actions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),why_analysis_id uuid NOT NULL REFERENCES public.weakness_why_analysis(id) ON DELETE CASCADE,sort_order integer NOT NULL CHECK(sort_order>0),rencana_tindakan text NOT NULL,pic text NOT NULL,due_date date NOT NULL,status text NOT NULL DEFAULT 'Belum Mulai' CHECK(status IN('Belum Mulai','Berjalan','Selesai')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(why_analysis_id,sort_order));
CREATE INDEX idx_weakness_reports_program ON public.weakness_analysis_reports(program_id); CREATE INDEX idx_weakness_items_report ON public.weakness_analysis_report_items(report_id); CREATE INDEX idx_weakness_items_car ON public.weakness_analysis_report_items(car_id); CREATE INDEX idx_ai_suggestion_reuse ON public.ltp_ai_classification_suggestions(car_id,input_hash,prompt_version,model,created_at DESC); CREATE INDEX idx_weakness_why_report ON public.weakness_why_analysis(report_id); CREATE INDEX idx_weakness_actions_why ON public.weakness_actions(why_analysis_id);
CREATE TRIGGER set_weakness_reports_updated_at BEFORE UPDATE ON public.weakness_analysis_reports FOR EACH ROW EXECUTE FUNCTION public.update_updated_at(); CREATE TRIGGER set_ltp_analysis_classifications_updated_at BEFORE UPDATE ON public.ltp_analysis_classifications FOR EACH ROW EXECUTE FUNCTION public.update_updated_at(); CREATE TRIGGER set_weakness_why_updated_at BEFORE UPDATE ON public.weakness_why_analysis FOR EACH ROW EXECUTE FUNCTION public.update_updated_at(); CREATE TRIGGER set_weakness_levels_updated_at BEFORE UPDATE ON public.weakness_why_levels FOR EACH ROW EXECUTE FUNCTION public.update_updated_at(); CREATE TRIGGER set_weakness_actions_updated_at BEFORE UPDATE ON public.weakness_actions FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();

CREATE FUNCTION public.assert_weakness_draft(p_report_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NOT public.can_manage_weakness_analysis() THEN RAISE EXCEPTION 'Akses Weakness Analysis ditolak';END IF;IF NOT EXISTS(SELECT 1 FROM public.weakness_analysis_reports WHERE id=p_report_id AND status='Draft') THEN RAISE EXCEPTION 'Analisa tidak ditemukan atau sudah Final';END IF;END$$;
CREATE FUNCTION public.populate_weakness_report(p_report_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_r public.weakness_analysis_reports%ROWTYPE;v_n integer;BEGIN PERFORM public.assert_weakness_draft(p_report_id);SELECT * INTO v_r FROM public.weakness_analysis_reports WHERE id=p_report_id FOR UPDATE;DELETE FROM public.weakness_analysis_report_items WHERE report_id=p_report_id;INSERT INTO public.weakness_analysis_report_items(report_id,finding_id,car_id,sort_order) SELECT p_report_id,f.id,c.id,row_number()OVER(ORDER BY r.tanggal_pelaksanaan_audit,f.kode_temuan,f.id) FROM public.findings f JOIN public.cars c ON c.finding_id=f.id JOIN public.audit_instruction_rows r ON r.id=f.instruction_row_id JOIN public.audit_instructions i ON i.id=r.instruction_id WHERE f.review_status IN('PUBLISHED','LEGACY_ESTABLISHED') AND ((v_r.source_mode='PROGRAM' AND i.program_id=v_r.program_id) OR (v_r.source_mode='DATE_RANGE' AND r.tanggal_pelaksanaan_audit BETWEEN v_r.periode_mulai AND v_r.periode_selesai));GET DIAGNOSTICS v_n=ROW_COUNT;UPDATE public.weakness_analysis_reports SET revision_version=revision_version+1 WHERE id=p_report_id;RETURN v_n;END$$;
CREATE FUNCTION public.create_weakness_analysis(p_judul text,p_source_mode text,p_periode_mulai date,p_periode_selesai date,p_program_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE v_id uuid;BEGIN IF NOT public.can_manage_weakness_analysis() THEN RAISE EXCEPTION 'Akses Weakness Analysis ditolak';END IF;INSERT INTO public.weakness_analysis_reports(judul,source_mode,periode_mulai,periode_selesai,program_id,created_by,pj_qms) SELECT btrim(p_judul),p_source_mode,p_periode_mulai,p_periode_selesai,p_program_id,auth.uid(),CASE WHEN p_source_mode='PROGRAM' THEN ap.penanggung_jawab_qms END FROM (SELECT 1)x LEFT JOIN public.audit_programs ap ON ap.id=p_program_id RETURNING id INTO v_id;PERFORM public.populate_weakness_report(v_id);RETURN v_id;END$$;
CREATE FUNCTION public.approve_ltp_analysis_classification(p_car_id uuid,p_4m1e text,p_dis text,p_problem_type text,p_source text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$BEGIN IF NOT public.can_manage_weakness_analysis() THEN RAISE EXCEPTION 'Akses Weakness Analysis ditolak';END IF;IF NOT EXISTS(SELECT 1 FROM public.weakness_analysis_report_items x JOIN public.weakness_analysis_reports r ON r.id=x.report_id WHERE x.car_id=p_car_id AND r.status='Draft') THEN RAISE EXCEPTION 'LTP tidak berada pada Analisa Draft';END IF;INSERT INTO public.ltp_analysis_classifications(car_id,approved_4m1e,approved_dis,approved_problem_type,approved_by,approved_at,approval_source)VALUES(p_car_id,p_4m1e,p_dis,p_problem_type,auth.uid(),now(),p_source)ON CONFLICT(car_id)DO UPDATE SET approved_4m1e=excluded.approved_4m1e,approved_dis=excluded.approved_dis,approved_problem_type=excluded.approved_problem_type,approved_by=auth.uid(),approved_at=now(),approval_source=excluded.approval_source;END$$;
CREATE FUNCTION public.save_weakness_analysis_draft(p_report_id uuid,p_expected_revision integer,p_kesimpulan text,p_leader uuid,p_pj_qms text,p_why jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE v_rev integer;w jsonb;v_wid uuid;l jsonb;a jsonb;BEGIN PERFORM public.assert_weakness_draft(p_report_id);SELECT revision_version INTO v_rev FROM public.weakness_analysis_reports WHERE id=p_report_id FOR UPDATE;IF v_rev<>p_expected_revision THEN RAISE EXCEPTION 'WEAKNESS_STALE_REVISION';END IF;UPDATE public.weakness_analysis_reports SET kesimpulan=p_kesimpulan,audit_team_leader_auditor_id=p_leader,pj_qms=p_pj_qms,revision_version=revision_version+1 WHERE id=p_report_id;DELETE FROM public.weakness_why_analysis WHERE report_id=p_report_id;FOR w IN SELECT * FROM jsonb_array_elements(COALESCE(p_why,'[]')) LOOP INSERT INTO public.weakness_why_analysis(report_id,nomor,problem,akar_permasalahan,sort_order)VALUES(p_report_id,(w->>'nomor')::integer,w->>'problem',w->>'akar_permasalahan',(w->>'sort_order')::integer)RETURNING id INTO v_wid;FOR l IN SELECT * FROM jsonb_array_elements(COALESCE(w->'levels','[]')) LOOP INSERT INTO public.weakness_why_levels(why_analysis_id,level,teks)VALUES(v_wid,(l->>'level')::integer,l->>'teks');END LOOP;FOR a IN SELECT * FROM jsonb_array_elements(COALESCE(w->'actions','[]')) LOOP INSERT INTO public.weakness_actions(why_analysis_id,sort_order,rencana_tindakan,pic,due_date,status)VALUES(v_wid,(a->>'sort_order')::integer,a->>'rencana_tindakan',a->>'pic',(a->>'due_date')::date,a->>'status');END LOOP;END LOOP;RETURN v_rev+1;END$$;
CREATE FUNCTION public.finalize_weakness_analysis(p_report_id uuid,p_expected_revision integer) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$DECLARE r public.weakness_analysis_reports%ROWTYPE;BEGIN IF NOT public.can_manage_weakness_analysis() THEN RAISE EXCEPTION 'Akses Weakness Analysis ditolak';END IF;SELECT * INTO r FROM public.weakness_analysis_reports WHERE id=p_report_id FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Analisa tidak ditemukan';END IF;IF r.status<>'Draft' THEN RAISE EXCEPTION 'Analisa bukan Draft';END IF;IF r.revision_version<>p_expected_revision THEN RAISE EXCEPTION 'WEAKNESS_STALE_REVISION';END IF;IF btrim(COALESCE(r.kesimpulan,''))='' THEN RAISE EXCEPTION 'Kesimpulan wajib diisi';END IF;IF NOT EXISTS(SELECT 1 FROM public.weakness_analysis_report_items WHERE report_id=r.id) THEN RAISE EXCEPTION 'Populasi Finding kosong';END IF;IF EXISTS(SELECT 1 FROM public.weakness_analysis_report_items x LEFT JOIN public.findings f ON f.id=x.finding_id AND f.review_status IN('PUBLISHED','LEGACY_ESTABLISHED') LEFT JOIN public.cars c ON c.id=x.car_id AND c.finding_id=x.finding_id WHERE x.report_id=r.id AND(f.id IS NULL OR c.id IS NULL))THEN RAISE EXCEPTION 'Relasi Finding/LTP tidak lagi valid';END IF;IF EXISTS(SELECT 1 FROM public.weakness_analysis_report_items x JOIN public.cars c ON c.id=x.car_id WHERE x.report_id=r.id AND c.status<>'CLOSED')THEN RAISE EXCEPTION 'Masih terdapat LTP yang belum Closed.';END IF;IF EXISTS(SELECT 1 FROM public.weakness_analysis_report_items x LEFT JOIN public.ltp_analysis_classifications c ON c.car_id=x.car_id WHERE x.report_id=r.id AND(c.car_id IS NULL OR c.approved_4m1e IS NULL OR c.approved_dis IS NULL OR c.approved_problem_type IS NULL))THEN RAISE EXCEPTION 'Klasifikasi seluruh item wajib disetujui';END IF;IF EXISTS(SELECT 1 FROM public.weakness_why_analysis w WHERE w.report_id=r.id AND(btrim(w.problem)='' OR btrim(w.akar_permasalahan)='')) OR EXISTS(SELECT 1 FROM public.weakness_why_analysis w JOIN public.weakness_why_levels l ON l.why_analysis_id=w.id WHERE w.report_id=r.id AND(l.level NOT BETWEEN 1 AND 4 OR btrim(l.teks)='')) OR EXISTS(SELECT 1 FROM public.weakness_why_analysis w JOIN public.weakness_actions a ON a.why_analysis_id=w.id WHERE w.report_id=r.id AND(btrim(a.rencana_tindakan)='' OR btrim(a.pic)='' OR a.due_date IS NULL)) THEN RAISE EXCEPTION 'Why-Why atau Tindakan belum lengkap';END IF;UPDATE public.weakness_analysis_report_items x SET final_4m1e=c.approved_4m1e,final_dis=c.approved_dis,final_problem_type=c.approved_problem_type FROM public.ltp_analysis_classifications c WHERE x.report_id=r.id AND c.car_id=x.car_id;UPDATE public.weakness_analysis_reports SET status='Final',finalized_at=now(),revision_version=revision_version+1,audit_team_leader_name_snapshot=(SELECT nama FROM public.auditors WHERE id=r.audit_team_leader_auditor_id),pj_qms_snapshot=r.pj_qms WHERE id=r.id;RETURN r.revision_version+1;END$$;

CREATE FUNCTION public.protect_weakness_final() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$BEGIN IF OLD.status='Final' THEN RAISE EXCEPTION 'FORM-010 Final bersifat immutable';END IF;RETURN NEW;END$$;
CREATE TRIGGER protect_weakness_final_report BEFORE UPDATE OR DELETE ON public.weakness_analysis_reports FOR EACH ROW EXECUTE FUNCTION public.protect_weakness_final();
CREATE FUNCTION public.protect_weakness_child() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$DECLARE rid uuid;BEGIN rid:=CASE TG_TABLE_NAME WHEN 'weakness_analysis_report_items' THEN COALESCE(NEW.report_id,OLD.report_id) WHEN 'weakness_why_analysis' THEN COALESCE(NEW.report_id,OLD.report_id) WHEN 'weakness_why_levels' THEN (SELECT report_id FROM public.weakness_why_analysis WHERE id=COALESCE(NEW.why_analysis_id,OLD.why_analysis_id)) ELSE (SELECT report_id FROM public.weakness_why_analysis WHERE id=COALESCE(NEW.why_analysis_id,OLD.why_analysis_id)) END;IF EXISTS(SELECT 1 FROM public.weakness_analysis_reports WHERE id=rid AND status='Final')THEN RAISE EXCEPTION 'FORM-010 Final bersifat immutable';END IF;RETURN COALESCE(NEW,OLD);END$$;
CREATE TRIGGER protect_weakness_items BEFORE INSERT OR UPDATE OR DELETE ON public.weakness_analysis_report_items FOR EACH ROW EXECUTE FUNCTION public.protect_weakness_child();CREATE TRIGGER protect_weakness_why BEFORE INSERT OR UPDATE OR DELETE ON public.weakness_why_analysis FOR EACH ROW EXECUTE FUNCTION public.protect_weakness_child();CREATE TRIGGER protect_weakness_levels BEFORE INSERT OR UPDATE OR DELETE ON public.weakness_why_levels FOR EACH ROW EXECUTE FUNCTION public.protect_weakness_child();CREATE TRIGGER protect_weakness_actions BEFORE INSERT OR UPDATE OR DELETE ON public.weakness_actions FOR EACH ROW EXECUTE FUNCTION public.protect_weakness_child();
CREATE FUNCTION public.reject_ai_suggestion_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$BEGIN RAISE EXCEPTION 'Riwayat AI bersifat append-only';END$$;CREATE TRIGGER immutable_ai_suggestions BEFORE UPDATE OR DELETE ON public.ltp_ai_classification_suggestions FOR EACH ROW EXECUTE FUNCTION public.reject_ai_suggestion_mutation();

ALTER TABLE public.weakness_analysis_reports ENABLE ROW LEVEL SECURITY;ALTER TABLE public.weakness_analysis_report_items ENABLE ROW LEVEL SECURITY;ALTER TABLE public.ltp_analysis_classifications ENABLE ROW LEVEL SECURITY;ALTER TABLE public.ltp_ai_classification_suggestions ENABLE ROW LEVEL SECURITY;ALTER TABLE public.weakness_why_analysis ENABLE ROW LEVEL SECURITY;ALTER TABLE public.weakness_why_levels ENABLE ROW LEVEL SECURITY;ALTER TABLE public.weakness_actions ENABLE ROW LEVEL SECURITY;
CREATE POLICY weakness_reports_read ON public.weakness_analysis_reports FOR SELECT TO authenticated USING(public.can_manage_weakness_analysis());CREATE POLICY weakness_items_read ON public.weakness_analysis_report_items FOR SELECT TO authenticated USING(public.can_manage_weakness_analysis());CREATE POLICY weakness_classifications_read ON public.ltp_analysis_classifications FOR SELECT TO authenticated USING(public.can_manage_weakness_analysis());CREATE POLICY weakness_ai_read ON public.ltp_ai_classification_suggestions FOR SELECT TO authenticated USING(public.can_manage_weakness_analysis());CREATE POLICY weakness_why_read ON public.weakness_why_analysis FOR SELECT TO authenticated USING(public.can_manage_weakness_analysis());CREATE POLICY weakness_levels_read ON public.weakness_why_levels FOR SELECT TO authenticated USING(public.can_manage_weakness_analysis());CREATE POLICY weakness_actions_read ON public.weakness_actions FOR SELECT TO authenticated USING(public.can_manage_weakness_analysis());
REVOKE ALL ON public.weakness_analysis_reports,public.weakness_analysis_report_items,public.ltp_analysis_classifications,public.ltp_ai_classification_suggestions,public.weakness_why_analysis,public.weakness_why_levels,public.weakness_actions FROM PUBLIC,anon,authenticated;GRANT SELECT ON public.weakness_analysis_reports,public.weakness_analysis_report_items,public.ltp_analysis_classifications,public.ltp_ai_classification_suggestions,public.weakness_why_analysis,public.weakness_why_levels,public.weakness_actions TO authenticated;GRANT INSERT ON public.ltp_ai_classification_suggestions TO service_role;
REVOKE ALL ON FUNCTION public.can_manage_weakness_analysis(),public.assert_weakness_draft(uuid),public.populate_weakness_report(uuid),public.create_weakness_analysis(text,text,date,date,uuid),public.approve_ltp_analysis_classification(uuid,text,text,text,text),public.save_weakness_analysis_draft(uuid,integer,text,uuid,text,jsonb),public.finalize_weakness_analysis(uuid,integer) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.can_manage_weakness_analysis(),public.populate_weakness_report(uuid),public.create_weakness_analysis(text,text,date,date,uuid),public.approve_ltp_analysis_classification(uuid,text,text,text,text),public.save_weakness_analysis_draft(uuid,integer,text,uuid,text,jsonb),public.finalize_weakness_analysis(uuid,integer) TO authenticated;
